import{_ as i,c as a,o as t,a7 as s}from"./chunks/framework.D0mml042.js";const h=JSON.parse('{"title":"Virga Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),n={name:"guide/security.md"};function r(o,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /virga/guide/security.md for this page in Markdown format</div><h1 id="virga-security-model" tabindex="-1">Virga Security Model <a class="header-anchor" href="#virga-security-model" aria-label="Permalink to &quot;Virga Security Model&quot;">​</a></h1><p>This document outlines the security architecture and best practices for deploying and operating the Virgaramework. Understanding these concepts is crucial for maintaining operational security (OPSEC) and protecting both your infrastructure and your targets.</p><h2 id="guiding-principles" tabindex="-1">Guiding Principles <a class="header-anchor" href="#guiding-principles" aria-label="Permalink to &quot;Guiding Principles&quot;">​</a></h2><ul><li><strong>Defense in Depth</strong>: Security is implemented in layers, from network communication to implant behavior.</li><li><strong>Configurability</strong>: Security features are designed to be adaptable to different operational scenarios.</li><li><strong>Transparency</strong>: This document aims to be transparent about the current security features and their limitations.</li></ul><h2 id="communication-security" tabindex="-1">Communication Security <a class="header-anchor" href="#communication-security" aria-label="Permalink to &quot;Communication Security&quot;">​</a></h2><p>Securing the communication channel between the beacon and the C2 server is fundamental.</p><h3 id="transport-layer-security" tabindex="-1">Transport Layer Security <a class="header-anchor" href="#transport-layer-security" aria-label="Permalink to &quot;Transport Layer Security&quot;">​</a></h3><ul><li><strong>HTTPS Listeners</strong>: It is strongly recommended to use <code>https</code> listeners for all production deployments. This encrypts traffic at the transport layer using TLS, protecting against eavesdropping and man-in-the-middle (MitM) attacks.</li><li><strong>SSL/TLS Certificates</strong>: Use valid, trusted SSL/TLS certificates. While self-signed certificates can work for testing, they are easily detectable. Services like Let&#39;s Encrypt provide free, trusted certificates.</li></ul><h3 id="application-layer-encryption" tabindex="-1">Application Layer Encryption <a class="header-anchor" href="#application-layer-encryption" aria-label="Permalink to &quot;Application Layer Encryption&quot;">​</a></h3><ul><li><p><strong>AES-256-GCM</strong>: All beacon communication is encrypted at the application layer using AES-256-GCM. This provides an additional layer of security, ensuring that even if TLS is compromised, the C2 traffic remains confidential.</p></li><li><p><strong>Encryption Key Management</strong>:</p><blockquote><p><strong>⚠️ CRITICAL WARNING:</strong> The default configuration uses a static, publicly known encryption key (<code>change-this-key-in-production-environment</code>). You <strong>MUST</strong> generate a unique, strong key for each deployment. Using the default key makes your C2 traffic trivial to decrypt.</p></blockquote><p><strong>Generate a secure key using the provided script:</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/generate-secure-key.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Or generate manually:</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate a strong, random 32-byte key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set as environment variable (recommended)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VIRGA_ENCRYPTION_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;your-generated-key-here&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>Configuration example:</strong></p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listeners</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">encryption</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${VIRGA_ENCRYPTION_KEY}</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Use environment variable</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">aes-256</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li></ul><h2 id="implant-security" tabindex="-1">Implant Security <a class="header-anchor" href="#implant-security" aria-label="Permalink to &quot;Implant Security&quot;">​</a></h2><p>The security of the beacon implant itself is vital to avoid detection.</p><h3 id="in-memory-operations" tabindex="-1">In-Memory Operations <a class="header-anchor" href="#in-memory-operations" aria-label="Permalink to &quot;In-Memory Operations&quot;">​</a></h3><ul><li><strong>MemDB</strong>: The AI-powered features use an in-memory database (<code>go-memdb</code>) to store operational data. This minimizes the disk footprint on the target system, making forensic analysis more difficult.</li><li><strong>Self-Deletion</strong>: The <code>self_delete</code> option in the generator configuration, when enabled, attempts to remove the beacon binary from the disk after execution.</li></ul><h3 id="obfuscation-and-evasion" tabindex="-1">Obfuscation and Evasion <a class="header-anchor" href="#obfuscation-and-evasion" aria-label="Permalink to &quot;Obfuscation and Evasion&quot;">​</a></h3><ul><li><strong>Code Obfuscation (<code>obfuscation: true</code>)</strong>: This feature is <strong>planned</strong> to automatically obfuscate the beacon&#39;s code, including string encryption and dynamic API resolution, to make reverse engineering more challenging.</li><li><strong>Anti-AV (<code>anti_av: true</code>)</strong>: This feature is <strong>planned</strong> to incorporate techniques to bypass or disable common antivirus products.</li><li><strong>Anti-ETW (<code>anti_etw: true</code>)</strong>: This feature is <strong>planned</strong> to include methods for patching Event Tracing for Windows (ETW) to reduce logging of malicious activities.</li></ul><blockquote><p><strong>Note</strong>: As of the current version, these advanced evasion features are not yet implemented. Rely on other OPSEC measures for stealth.</p></blockquote><h2 id="server-security" tabindex="-1">Server Security <a class="header-anchor" href="#server-security" aria-label="Permalink to &quot;Server Security&quot;">​</a></h2><p>Protecting the C2 server is as important as securing the implants.</p><ul><li><strong>Admin API Access</strong>: The admin port (default: <code>8443</code>) should be firewalled and accessible only from trusted IP addresses. Exposing it to the public internet is a significant risk.</li><li><strong>Database Security</strong>: The SQLite database (<code>virga.db</code>) contains sensitive information, including session data, target information, and task history. Ensure the file has appropriate permissions and is encrypted at rest if required by your environment.</li><li><strong>Logging</strong>: Monitor server logs (<code>logs/server.log</code>) for suspicious activity. In a production environment, consider shipping logs to a secure, centralized logging solution.</li></ul><h2 id="operational-security-opsec-best-practices" tabindex="-1">Operational Security (OPSEC) Best Practices <a class="header-anchor" href="#operational-security-opsec-best-practices" aria-label="Permalink to &quot;Operational Security (OPSEC) Best Practices&quot;">​</a></h2><ul><li><strong>Listener Profiles</strong>: Customize your listener profiles to mimic legitimate web traffic. Use common <code>uri_path</code> values and consider using a redirector to hide the true location of your C2 server.</li><li><strong>User-Agent</strong>: Change the default <code>user_agent</code> in your generator settings to blend in with the target environment.</li><li><strong>Jitter</strong>: Always use a <code>jitter</code> value (e.g., 20-30%) to randomize beacon check-in intervals, making traffic analysis more difficult.</li><li><strong>Legal and Ethical Use</strong>: This tool is intended for authorized security testing and research only. Unauthorized use is illegal and unethical. Always adhere to the law and obtain explicit permission before using Virga</li></ul>`,23)])])}const g=i(n,[["render",r]]);export{h as __pageData,g as default};
